'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var bench = require( '@stdlib/bench' );
var pow = require( '@stdlib/math/base/special/pow' );
var format = require( '@stdlib/string/format' );
var Complex128Matrix = require( '@stdlib/ndarray/matrix/complex128' );
var uniform = require( '@stdlib/random/array/uniform' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var real = require( '@stdlib/complex/float64/real' );
var tryRequire = require( '@stdlib/utils/try-require' );
var pkg = require( './../package.json' ).name;


// VARIABLES //

var ztril = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( ztril instanceof Error )
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} N - number of rows and columns
* @returns {Function} benchmark function
*/
function createBenchmark( N ) {
	var abuf;
	var bbuf;
	var A;
	var B;
	var k;

	abuf = uniform( N*N*2, -100.0, 100.0, {
		'dtype': 'float64'
	});
	bbuf = uniform( N*N*2, -100.0, 100.0, {
		'dtype': 'float64'
	});
	A = new Complex128Matrix( abuf.buffer, 0, N, N );
	B = new Complex128Matrix( bbuf.buffer, 0, N, N );
	k = scalar2ndarray( 0, {
		'dtype': 'int32'
	});

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var out;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			out = ztril( [ A, B, k ] );
			if ( typeof out !== 'object' ) {
				b.fail( 'should return an ndarray' );
			}
		}
		b.toc();
		if ( isnan( real( out.get( i%N, i%N ) ) ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var N;
	var f;
	var i;

	min = 1; // 10^min
	max = 3; // 10^max

	for ( i = min; i <= max; i++ ) {
		N = pow( 10, i );
		f = createBenchmark( N );
		bench( format( '%s::native:size=%d', pkg, N*N ), opts, f );
	}
}

main();
